"""Subscription-auth validation for both lanes' binaries.

No API key, base-URL override, cloud-provider override, or auth-token
override is permitted for ANY lane, codex or claude. A subscription/ChatGPT
login alone is not proof overage is disabled, so these checks only confirm
the CLI reports the expected first-party subscription session; they never
claim to prove billing overage is off. No secret values are ever printed;
only field names and lane-relevant status are included in failure reasons.

REMAINING TRUST BOUNDARY: this module can only see and block environment
variables. A provider override configured through a *config file* instead
(e.g. a `model_provider`/base-URL entry in `~/.codex/config.toml`, or an
equivalent Claude settings file) is not introspectable from here and is
NOT detected or blocked by this module. That gap is a real, documented
host trust boundary, not something this router claims to close — do not
read the presence of `check_claude_auth`/`check_codex_auth` as a hard
cost cap; it isn't one.
"""

from __future__ import annotations

import json
import os
import subprocess
from dataclasses import dataclass
from typing import Callable, Optional, Sequence

Runner = Callable[[Sequence[str]], "subprocess.CompletedProcess"]

# Applies to every lane, regardless of binary: API keys, base-URL overrides,
# cloud-provider overrides (Bedrock/Vertex), and auth-token overrides are all
# blocked. This is a superset of the old claude-only list.
BLOCKED_ENV_VARS = (
    "ANTHROPIC_API_KEY",
    "CLAUDE_API_KEY",
    "ANTHROPIC_AUTH_TOKEN",
    "ANTHROPIC_BASE_URL",
    "CLAUDE_CODE_USE_BEDROCK",
    "CLAUDE_CODE_USE_VERTEX",
    "CLAUDE_CODE_USE_FOUNDRY",
    "ANTHROPIC_VERTEX_PROJECT_ID",
    "CLOUD_ML_REGION",
    "AWS_BEARER_TOKEN_BEDROCK",
    "OPENAI_API_KEY",
    "OPENAI_BASE_URL",
    "CODEX_API_KEY",
)


@dataclass(frozen=True)
class AuthCheckResult:
    ok: bool
    reason: str


def _default_runner(argv: Sequence[str]) -> "subprocess.CompletedProcess":
    return subprocess.run(
        list(argv),
        capture_output=True,
        text=True,
        timeout=20,
        shell=False,
    )


def _env_override_reason(env: dict) -> Optional[str]:
    for var in BLOCKED_ENV_VARS:
        if env.get(var):
            return f"blocked: {var} is set; API-key/provider overrides are not permitted"
    return None


def check_claude_auth(
    runner: Optional[Runner] = None,
    env: Optional[dict] = None,
) -> AuthCheckResult:
    """Block dispatch unless the CLI reports a first-party claude.ai/max
    subscription session (parsed from `claude auth status --json`, not a
    free-form substring match) and no override env var is present.
    """
    env = os.environ if env is None else env
    override_reason = _env_override_reason(env)
    if override_reason:
        return AuthCheckResult(False, override_reason)

    runner = runner or _default_runner
    try:
        result = runner(["claude", "auth", "status", "--json"])
    except (FileNotFoundError, OSError) as exc:
        return AuthCheckResult(False, f"could not run 'claude auth status --json': {exc}")
    except subprocess.TimeoutExpired:
        return AuthCheckResult(False, "'claude auth status --json' timed out")

    if result.returncode != 0:
        return AuthCheckResult(
            False, f"'claude auth status --json' exited {result.returncode}"
        )

    try:
        data = json.loads(result.stdout or "")
    except json.JSONDecodeError as exc:
        return AuthCheckResult(False, f"'claude auth status --json' output is not valid JSON: {exc}")

    if not isinstance(data, dict):
        return AuthCheckResult(False, "'claude auth status --json' did not return a JSON object")

    if data.get("loggedIn") is not True:
        return AuthCheckResult(False, "claude auth status reports loggedIn is not true")
    if data.get("authMethod") != "claude.ai":
        return AuthCheckResult(False, "claude auth status authMethod is not 'claude.ai'")
    if data.get("subscriptionType") != "max":
        return AuthCheckResult(False, "claude auth status subscriptionType is not 'max'")
    if data.get("apiProvider") != "firstParty":
        return AuthCheckResult(False, "claude auth status apiProvider is not 'firstParty'")

    return AuthCheckResult(True, "claude.ai/max first-party subscription session confirmed")


def check_codex_auth(
    runner: Optional[Runner] = None,
    env: Optional[dict] = None,
) -> AuthCheckResult:
    """Block dispatch unless `codex login status` reports a ChatGPT login
    and no override env var is present.

    `codex login status` has no --json flag (verified via `codex login
    status --help`); it prints one of: "Logged in using ChatGPT", "Logged
    in using an API key", or a not-logged-in message. This checks that
    exact text rather than guessing a structured shape that does not exist.
    """
    env = os.environ if env is None else env
    override_reason = _env_override_reason(env)
    if override_reason:
        return AuthCheckResult(False, override_reason)

    runner = runner or _default_runner
    try:
        result = runner(["codex", "login", "status"])
    except (FileNotFoundError, OSError) as exc:
        return AuthCheckResult(False, f"could not run 'codex login status': {exc}")
    except subprocess.TimeoutExpired:
        return AuthCheckResult(False, "'codex login status' timed out")

    if result.returncode != 0:
        return AuthCheckResult(
            False, f"'codex login status' exited {result.returncode}"
        )

    output = (result.stdout or "") + (result.stderr or "")
    lowered = output.lower()
    if "api key" in lowered:
        return AuthCheckResult(
            False, "'codex login status' reports an API-key login; ChatGPT login is required"
        )
    if "logged in using chatgpt" not in lowered:
        return AuthCheckResult(
            False, "'codex login status' did not report a ChatGPT login"
        )

    return AuthCheckResult(True, "ChatGPT login confirmed")

"""Usage/resource-state validation.

TRUST BOUNDARY: this router does not call any provider API and does not
invent a usage-limit endpoint. It reads a JSON file the caller supplies
(default path is a per-host location the caller or an existing native tool
is expected to keep current), and treats that file as the only source of
truth for "is ordinary usage available for this lane". If that file is
missing, unreadable, stale, or reports the lane as exhausted/unsafe, this
module fails closed: dispatch is blocked. This module never queries a
provider, never fabricates a cost cap, and never falls back to a paid or
API-key path on its own.

`paid_fallback_allowed` is a host-maintained ATTESTATION, not a provider
enforcement mechanism and not a real cost cap: this module has no way to
verify a provider account cannot actually be billed. It only refuses to
proceed unless the caller has explicitly written `false` for that field.
A caller who lies in this file, or who separately sets a provider override
this router cannot introspect (a config file, not an env var — see
router.auth), defeats this check; that residual trust boundary is real
and is documented here rather than glossed over.

Expected JSON shape (all keys required unless noted):
{
  "generated_at": "<ISO-8601 UTC timestamp>",
  "paid_fallback_allowed": false,
  "lanes": {
    "luna":   {"available": true, "exhausted": false, "unsafe": false},
    "terra":  {"available": true, "exhausted": false, "unsafe": false},
    "claude": {"available": true, "exhausted": false, "unsafe": false},
    "astra":  {"available": true, "exhausted": false, "unsafe": false}
  }
}
`astra` is REQUIRED in `lanes` like every other lane: astra's named-approval
requirement (see router.dispatch) is an additional gate on top of this
check, never a substitute for it. There is no lane exempt from usage
validation.
"""

from __future__ import annotations

import json
from dataclasses import dataclass
from datetime import datetime, timezone
from pathlib import Path
from typing import Optional

DEFAULT_MAX_AGE_SECONDS = 300  # 5 minutes


@dataclass(frozen=True)
class UsageCheckResult:
    ok: bool
    reason: str


def _parse_timestamp(value: str) -> datetime:
    # Accept trailing "Z" as UTC.
    if value.endswith("Z"):
        value = value[:-1] + "+00:00"
    dt = datetime.fromisoformat(value)
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return dt


def check_usage(
    lane: str,
    state_path: Path,
    now: Optional[datetime] = None,
    max_age_seconds: int = DEFAULT_MAX_AGE_SECONDS,
) -> UsageCheckResult:
    """Validate that `lane` is safe to dispatch to, per the usage state file.

    Fails closed (ok=False) on: missing file, unreadable/invalid JSON, a
    non-object body, missing/wrong-type fields, an unparsable/stale/future
    timestamp, `paid_fallback_allowed` missing or not exactly `False`, or
    the lane reporting exhausted/unsafe/unavailable. Applies identically to
    every lane, including `astra`.
    """
    now = now or datetime.now(timezone.utc)

    if not state_path.exists():
        return UsageCheckResult(False, f"usage state file not found: {state_path}")

    try:
        raw = state_path.read_text(encoding="utf-8")
    except OSError as exc:
        return UsageCheckResult(False, f"usage state file unreadable: {exc}")

    try:
        data = json.loads(raw)
    except json.JSONDecodeError as exc:
        return UsageCheckResult(False, f"usage state file is not valid JSON: {exc}")

    # A malformed top-level shape (e.g. a JSON array or scalar) must fail
    # closed, not crash on the first .get() call.
    if not isinstance(data, dict):
        return UsageCheckResult(
            False, f"usage state file must be a JSON object, got {type(data).__name__}"
        )

    generated_at = data.get("generated_at")
    if not isinstance(generated_at, str) or not generated_at.strip():
        return UsageCheckResult(False, "usage state 'generated_at' must be a non-empty string timestamp")

    try:
        generated_dt = _parse_timestamp(generated_at)
    except (ValueError, TypeError) as exc:
        return UsageCheckResult(False, f"usage state 'generated_at' unparsable: {exc}")

    age_seconds = (now - generated_dt).total_seconds()
    if age_seconds < 0:
        return UsageCheckResult(False, "usage state 'generated_at' is in the future")
    if age_seconds > max_age_seconds:
        return UsageCheckResult(
            False,
            f"usage state is stale: {age_seconds:.0f}s old, max allowed {max_age_seconds}s",
        )

    if "paid_fallback_allowed" not in data:
        return UsageCheckResult(False, "usage state missing 'paid_fallback_allowed'")
    paid_fallback_allowed = data["paid_fallback_allowed"]
    if not isinstance(paid_fallback_allowed, bool):
        return UsageCheckResult(
            False,
            f"usage state 'paid_fallback_allowed' must be a boolean, got "
            f"{type(paid_fallback_allowed).__name__}",
        )
    if paid_fallback_allowed:
        return UsageCheckResult(
            False, "usage state 'paid_fallback_allowed' is true; this router will not dispatch"
        )

    lanes = data.get("lanes")
    if not isinstance(lanes, dict):
        return UsageCheckResult(False, "usage state missing 'lanes' object")

    lane_state = lanes.get(lane)
    if not isinstance(lane_state, dict):
        return UsageCheckResult(False, f"usage state missing entry for lane {lane!r}")

    for required_key in ("available", "exhausted", "unsafe"):
        if required_key not in lane_state:
            return UsageCheckResult(
                False, f"usage state for lane {lane!r} missing key {required_key!r}"
            )
        value = lane_state[required_key]
        # Strict bool only: a string "false", 0/1, or null must not be
        # silently coerced by Python truthiness (bool("false") is True).
        if not isinstance(value, bool):
            return UsageCheckResult(
                False,
                f"usage state for lane {lane!r} key {required_key!r} must be a boolean, "
                f"got {type(value).__name__}",
            )

    if lane_state["exhausted"]:
        return UsageCheckResult(False, f"lane {lane!r} usage is exhausted")
    if lane_state["unsafe"]:
        return UsageCheckResult(False, f"lane {lane!r} usage state flagged unsafe")
    if not lane_state["available"]:
        return UsageCheckResult(False, f"lane {lane!r} not marked available")

    return UsageCheckResult(True, f"lane {lane!r} usage ok as of {generated_at}")

"""Fail-closed validation of the real charlie-session-guard resource state.

TRUST BOUNDARY: this router does not compute machine load itself. It reads
the JSON file an existing local guard/hook already maintains (default path
~/.local/state/charlie-session-guard/status.json) and treats it as the only
source of truth for "is it safe to start new heavy work right now". If that
file is missing, unreadable, malformed, stale, timestamped in the future, or
reports defer_new_heavy_work=true, this module fails closed: dispatch is
blocked for every lane, including an already-approved astra lane. Astra
approval exempts the human-approval gate only; it never exempts this gate.

Real observed schema (2026-09-20, ~/.local/state/charlie-session-guard/status.json):
{
  "at": 1789912909.80599,          # float, unix seconds
  "level": 1,
  "defer_new_heavy_work": false,   # bool
  ...additional informational fields (load_1m, cpus, largest_processes, ...)
}
Only "at" and "defer_new_heavy_work" are required and validated here; the
guard is free to carry other informational fields this module ignores.

Freshness window: the guard schema itself does not document a staleness
contract, so this module applies a conservative default of 120 seconds
(tighter than usage.py's 5-minute window, because this is a live pressure
sample meant to reflect current machine load, not a slow-changing quota).
Callers needing a different window should pass max_age_seconds explicitly.
"""

from __future__ import annotations

import json
import math
from dataclasses import dataclass
from datetime import datetime, timezone
from pathlib import Path
from typing import Optional

DEFAULT_MAX_AGE_SECONDS = 120  # 2 minutes; see module docstring.


@dataclass(frozen=True)
class GuardCheckResult:
    ok: bool
    reason: str


def _is_finite_number(value: object) -> bool:
    # bool is a subclass of int in Python; explicitly exclude it so a JSON
    # `true`/`false` is never silently accepted as a timestamp.
    if isinstance(value, bool):
        return False
    if not isinstance(value, (int, float)):
        return False
    return math.isfinite(value)


def check_guard(
    state_path: Path,
    now: Optional[datetime] = None,
    max_age_seconds: int = DEFAULT_MAX_AGE_SECONDS,
) -> GuardCheckResult:
    """Validate that the machine is safe to start new heavy work on.

    Fails closed (ok=False) on: missing file, unreadable/invalid JSON, a
    non-object body, a missing/non-numeric/non-finite/negative/future 'at',
    a stale 'at', a missing or non-boolean 'defer_new_heavy_work', or
    defer_new_heavy_work=true. There is no unsafe default: any validation
    failure blocks, it never falls through to "assume safe".
    """
    now_ts = (now or datetime.now(timezone.utc)).timestamp()

    if not state_path.exists():
        return GuardCheckResult(False, f"guard state file not found: {state_path}")

    try:
        raw = state_path.read_text(encoding="utf-8")
    except OSError as exc:
        return GuardCheckResult(False, f"guard state file unreadable: {exc}")

    try:
        data = json.loads(raw)
    except json.JSONDecodeError as exc:
        return GuardCheckResult(False, f"guard state file is not valid JSON: {exc}")

    if not isinstance(data, dict):
        return GuardCheckResult(False, "guard state file is not a JSON object")

    at = data.get("at")
    if "at" not in data or not _is_finite_number(at):
        return GuardCheckResult(
            False, f"guard state 'at' must be a finite numeric unix timestamp, got {at!r}"
        )

    age_seconds = now_ts - at
    if age_seconds < 0:
        return GuardCheckResult(False, "guard state 'at' is in the future")
    if age_seconds > max_age_seconds:
        return GuardCheckResult(
            False,
            f"guard state is stale: {age_seconds:.0f}s old, max allowed {max_age_seconds}s",
        )

    if "defer_new_heavy_work" not in data:
        return GuardCheckResult(False, "guard state missing 'defer_new_heavy_work'")

    defer = data["defer_new_heavy_work"]
    if not isinstance(defer, bool):
        return GuardCheckResult(
            False,
            f"guard state 'defer_new_heavy_work' must be a boolean, got {type(defer).__name__}",
        )

    if defer:
        return GuardCheckResult(False, "guard state reports defer_new_heavy_work=true")

    return GuardCheckResult(True, f"guard state ok as of at={at}")
